which node && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log(tables);
" 2>/dev/null || strings /workspace/world.db | grep -i "High Priority" | head -20

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8');
const idx = text.indexOf('High Priority');
if (idx >= 0) {
  // Extract surrounding context
  const start = Math.max(0, idx - 200);
  const end = Math.min(buf.length, idx + 500);
  const snippet = buf.slice(start, end).toString('utf8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
  console.log(snippet);
}
"

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
const matches = text.match(/ethan[^\s]*@[^\s]*/gi);
console.log('Email matches:', matches);
" 2>/dev/null

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
// Search for ethan with surrounding context
const idx = text.indexOf('ethan');
if (idx >= 0) {
  for (let i = 0; i < 5; i++) {
    const pos = text.indexOf('ethan', i === 0 ? 0 : idx + 1);
    if (pos < 0) break;
    const start = Math.max(0, pos - 100);
    const end = Math.min(text.length, pos + 200);
    console.log('---');
    console.log(text.slice(start, end));
  }
}
" 2>/dev/null

node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const text = buf.toString('utf8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
// Get more context around ethan.it.specialist
const searchStr = 'ethan.it.specialist';
let pos = 0;
while ((pos = text.indexOf(searchStr, pos)) !== -1) {
  const start = Math.max(0, pos - 150);
  const end = Math.min(text.length, pos + 300);
  console.log('===');
  console.log(text.slice(start, end));
  pos += searchStr.length;
}
"
